<?php
 namespace QQWorld\Customer\Model\Plugin\CustomerRepository; class TransactionWrapper { protected $resourceModel; public function __construct( \QQWorld\Customer\Model\ResourceModel\Customer $resourceModel ) { $this->resourceModel = $resourceModel; } public function aroundSave( \QQWorld\Customer\Api\CustomerRepositoryInterface $subject, \Closure $proceed, \QQWorld\Customer\Api\Data\CustomerInterface $customer, $passwordHash = null ) { $this->resourceModel->beginTransaction(); try { $result = $proceed($customer, $passwordHash); $this->resourceModel->commit(); return $result; } catch (\Exception $e) { $this->resourceModel->rollBack(); throw $e; } } } 